import {
  ADMISSION_NUMBERING_NOT_READY,
  createStudentService,
  getAllStudentsService,
  getStudentByIdService,
  isAdmissionNumberConflict,
  updateStudentService,
  deleteStudentService,
  verifyStudentService,
} from "../services/student.service.js";

import {validateStudentInput} from "../utils/validateStudent.js"


export const createStudent = async (req, res) => {
  const validation = validateStudentInput(req.body);

  if (!validation.valid) {
    return res.status(400).json({
      message: validation.message,
    });
  }

  // Admission numbers are generated by the database; never accept one from the client.
  if (String(req.body.admission_number ?? "").trim()) {
    return res.status(400).json({
      message:
        "Admission numbers are generated automatically. Leave the admission number empty.",
    });
  }

  const {
    full_name,
    email,
    department,
    course,
    mode_of_entry,
    application_number,
    session,
  } = req.body;

  const { data, error } = await createStudentService({
    full_name,
    email,
    department,
    course,
    mode_of_entry,
    application_number,
    session,
  });

  if (error) {
    console.error("Insert student error:", error);

    if (error.code === ADMISSION_NUMBERING_NOT_READY) {
      return res.status(503).json({
        message:
          "Admission numbers can't be generated right now, so the student was not saved. Please contact the system administrator.",
      });
    }

    if (isAdmissionNumberConflict(error)) {
      return res.status(409).json({
        message:
          "Could not assign a unique admission number, so the student was not saved. Please try again.",
      });
    }

    if (error.code === "23505") {
      // Identify which unique field actually clashed for a clearer message.
      const detail = `${error.details || ""} ${error.message || ""}`.toLowerCase();
      let field = "email, admission number, or application number";
      if (detail.includes("email")) field = "email";
      else if (detail.includes("admission_number")) field = "admission number";
      else if (detail.includes("application_number")) field = "application number";

      return res.status(409).json({
        message: `A student with this ${field} already exists`,
      });
    }

    return res.status(500).json({
      message: "Failed to save student",
    });
  }

  return res.status(201).json({
    message: "Student saved successfully",
    student: data?.[0] || null,
  });
};

export const getAllStudents = async (req, res) => {
  const { data, error } = await getAllStudentsService();

  if (error) {
    return res.status(500).json({
      message: "Failed to fetch students",
    });
  }

  return res.status(200).json(data);
};

export const getStudentById = async (req, res) => {
  const { id } = req.params;

  const { data, error } = await getStudentByIdService(id);

  if (error || !data) {
    return res.status(404).json({
      message: "Student not found",
    });
  }

  return res.status(200).json(data);
};

export const updateStudent = async (req, res) => {
  const { id } = req.params;
  const updates = { ...req.body };

  if (Object.keys(updates).length === 0) {
    return res.status(400).json({
      message: "No update fields provided",
    });
  }

  if (
    updates.mode_of_entry &&
    !["UTME", "Direct Entry"].includes(updates.mode_of_entry)
  ) {
    return res.status(400).json({
      message: "Mode of entry must be either UTME or Direct Entry",
    });
  }

  // Admission numbers are generated once by the database and can't be edited.
  // The edit form sends the current value back unchanged, which is ignored.
  if (Object.hasOwn(updates, "admission_number")) {
    const { data: current, error: currentError } = await getStudentByIdService(id);

    if (currentError || !current) {
      return res.status(404).json({
        message: "Student not found",
      });
    }

    if ((updates.admission_number || null) !== (current.admission_number || null)) {
      return res.status(400).json({
        message: "Admission numbers are generated automatically and can't be changed.",
      });
    }

    delete updates.admission_number;

    if (Object.keys(updates).length === 0) {
      return res.status(200).json({
        message: "Student updated successfully",
        student: current,
      });
    }
  }

  const { data, error } = await updateStudentService(id, updates);

  if (error) {
    console.error("Update student error:", error);

    if (error.code === "23505") {
      return res.status(409).json({
        message:
          "A student with this email, admission number, or application number already exists",
      });
    }

    return res.status(500).json({
      message: "Failed to update student",
    });
  }

  if (!data || data.length === 0) {
    return res.status(404).json({
      message: "Student not found",
    });
  }

  return res.status(200).json({
    message: "Student updated successfully",
    student: data[0],
  });
};

export const deleteStudent = async (req, res) => {
  const { id } = req.params;

  const { data, error } = await deleteStudentService(id);

  if (error) {
    return res.status(500).json({
      message: "Failed to delete student",
    });
  }

  if (!data || data.length === 0) {
    return res.status(404).json({
      message: "Student not found",
    });
  }

  return res.status(200).json({
    message: "Student deleted successfully",
  });
};

export const verifyStudent = async (req, res) => {
  const { email, application_number } = req.body;

  if (!email || !application_number) {
    return res.status(400).json({
      message: "Email and application number are required",
    });
  }

  const { data, error } = await verifyStudentService(
    email,
    application_number
  );

  if (error || !data) {
    return res.status(404).json({
      message: "No matching admission record found",
    });
  }

  return res.status(200).json({
    message: "Student verified successfully",
    student: data,
  });
};